'use strict';

// MODULES //

var tape = require( 'tape' );
var isAlmostSameValuef = require( '@stdlib/number/float32/base/assert/is-almost-same-value' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isPositiveZerof = require( '@stdlib/math/base/assert/is-positive-zerof' );
var isNegativeZerof = require( '@stdlib/math/base/assert/is-negative-zerof' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var Complex64 = require( '@stdlib/complex/float32/ctor' );
var realf = require( '@stdlib/complex/float32/real' );
var imagf = require( '@stdlib/complex/float32/imag' );
var cexpf = require( './../lib' );


// FIXTURES //

var pureImaginary = require( './fixtures/julia/pure_imaginary.json' );
var generalComplex = require( './fixtures/julia/general_complex.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof cexpf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns a single-precision complex floating-point number', function test( t ) {
	var v;

	v = cexpf( new Complex64( 0.0, 0.0 ) );
	t.strictEqual( realf( v ), 1.0, 'returns expected value' );
	t.strictEqual( imagf( v ), 0.0, 'returns expected value' );
	t.end();
});

tape( 'the function computes exp(z) for pure imaginary z', function test( t ) {
	var expre;
	var expim;
	var re;
	var im;
	var i;
	var q;

	re = pureImaginary.re;
	im = pureImaginary.im;
	expre = pureImaginary.expre;
	expim = pureImaginary.expim;

	for ( i = 0; i < re.length; i++ ) {
		q = cexpf( new Complex64( re[ i ], im[ i ] ) );
		t.strictEqual( realf( q ), f32( expre[ i ] ), 'returns expected value' );
		t.strictEqual( imagf( q ), f32( expim[ i ] ), 'returns expected value' );
	}
	t.end();
});

tape( 'the function computes exp(z) for complex z', function test( t ) {
	var expre;
	var expim;
	var re;
	var im;
	var i;
	var q;

	re = generalComplex.re;
	im = generalComplex.im;
	expre = generalComplex.expre;
	expim = generalComplex.expim;

	for ( i = 0; i < re.length; i++ ) {
		q = cexpf( new Complex64( re[ i ], im[ i ] ) );
		t.strictEqual( isAlmostSameValuef( realf( q ), f32( expre[ i ] ), 2 ), true, 'returns expected value' );
		t.strictEqual( isAlmostSameValuef( imagf( q ), f32( expim[ i ] ), 2 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function returns `NaN` for both components if the imaginary component is `+Infinity`', function test( t ) {
	var v;

	v = cexpf( new Complex64( 0.0, PINF ) );
	t.strictEqual( isnanf( realf( v ) ), true, 'returns expected value' );
	t.strictEqual( isnanf( imagf( v ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `NaN` for both components if the imaginary component is `-Infinity`', function test( t ) {
	var v;

	v = cexpf( new Complex64( 0.0, NINF ) );
	t.strictEqual( isnanf( realf( v ) ), true, 'returns expected value' );
	t.strictEqual( isnanf( imagf( v ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `0` for both components if the real component is `-Infinity`', function test( t ) {
	var v;

	v = cexpf( new Complex64( NINF, 1.0 ) );
	t.strictEqual( realf( v ), 0.0, 'returns expected value' );
	t.strictEqual( imagf( v ), 0.0, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+Infinity` if the real component is `+Infinity` and the imaginary component is `0.0`', function test( t ) {
	var v;

	v = cexpf( new Complex64( PINF, 0.0 ) );
	t.strictEqual( realf( v ), PINF, 'returns expected value' );
	t.strictEqual( imagf( v ), 0.0, 'returns expected value' );
	t.end();
});

tape( 'the function returns `NaN` with imaginary `0.0` if the real component is `NaN` and the imaginary component is `0.0`', function test( t ) {
	var v;

	v = cexpf( new Complex64( NaN, 0.0 ) );
	t.strictEqual( isnanf( realf( v ) ), true, 'returns expected value' );
	t.strictEqual( imagf( v ), 0.0, 'returns expected value' );
	t.end();
});

tape( 'the function returns `NaN` for both components if the imaginary component is `NaN`', function test( t ) {
	var v;

	v = cexpf( new Complex64( 5.0, NaN ) );
	t.strictEqual( isnanf( realf( v ) ), true, 'returns expected value' );
	t.strictEqual( isnanf( imagf( v ) ), true, 'returns expected value' );

	v = cexpf( new Complex64( 0.0, NaN ) );
	t.strictEqual( isnanf( realf( v ) ), true, 'returns expected value' );
	t.strictEqual( isnanf( imagf( v ) ), true, 'returns expected value' );

	v = cexpf( new Complex64( NaN, NaN ) );
	t.strictEqual( isnanf( realf( v ) ), true, 'returns expected value' );
	t.strictEqual( isnanf( imagf( v ) ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `+0.0` imaginary component if the imaginary component is `+0.0`', function test( t ) {
	var v;

	v = cexpf( new Complex64( 3.0, 0.0 ) );
	t.strictEqual( isPositiveZerof( imagf( v ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-0.0` imaginary component if the imaginary component is `-0.0`', function test( t ) {
	var v;

	v = cexpf( new Complex64( 3.0, -0.0 ) );
	t.strictEqual( isNegativeZerof( imagf( v ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `NaN` for both components if the real component is `NaN` and the imaginary component is nonzero', function test( t ) {
	var v;

	v = cexpf( new Complex64( NaN, 3.0 ) );
	t.strictEqual( isnanf( realf( v ) ), true, 'returns expected value' );
	t.strictEqual( isnanf( imagf( v ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+0.0` imaginary component if the real component is `NaN` and the imaginary component is `+0.0`', function test( t ) {
	var v;

	v = cexpf( new Complex64( NaN, 0.0 ) );
	t.strictEqual( isnanf( realf( v ) ), true, 'returns expected value' );
	t.strictEqual( isPositiveZerof( imagf( v ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-0.0` imaginary component if the real component is `NaN` and the imaginary component is `-0.0`', function test( t ) {
	var v;

	v = cexpf( new Complex64( NaN, -0.0 ) );
	t.strictEqual( isnanf( realf( v ) ), true, 'returns expected value' );
	t.strictEqual( isNegativeZerof( imagf( v ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-Infinity` and `NaN` if the real component is `+Infinity` and the imaginary component is `+Infinity`', function test( t ) {
	var v;

	v = cexpf( new Complex64( PINF, PINF ) );
	t.strictEqual( realf( v ), NINF, 'returns expected value' );
	t.strictEqual( isnanf( imagf( v ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-0.0` and `+0.0` if the real component is `-Infinity` and the imaginary component is `+Infinity`', function test( t ) {
	var v;

	v = cexpf( new Complex64( NINF, PINF ) );
	t.strictEqual( isNegativeZerof( realf( v ) ), true, 'returns expected value' );
	t.strictEqual( isPositiveZerof( imagf( v ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-0.0` for both components if the real component is `-Infinity` and the imaginary component is `-Infinity`', function test( t ) {
	var v;

	v = cexpf( new Complex64( NINF, NINF ) );
	t.strictEqual( isNegativeZerof( realf( v ) ), true, 'returns expected value' );
	t.strictEqual( isNegativeZerof( imagf( v ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function computes exp(z) for pure real z (positive)', function test( t ) {
	var v;

	v = cexpf( new Complex64( 1.0, 0.0 ) );
	t.strictEqual( realf( v ), 2.7182817459106445, 'returns expected value' );
	t.strictEqual( isPositiveZerof( imagf( v ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function computes exp(z) for pure real z (negative)', function test( t ) {
	var v;

	v = cexpf( new Complex64( -1.0, 0.0 ) );
	t.strictEqual( realf( v ), 0.3678794503211975, 'returns expected value' );
	t.strictEqual( isPositiveZerof( imagf( v ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+Infinity` for large positive real component with zero imaginary component', function test( t ) {
	var v;

	v = cexpf( new Complex64( 89.0, 0.0 ) );
	t.strictEqual( realf( v ), PINF, 'returns expected value' );
	t.strictEqual( isPositiveZerof( imagf( v ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns infinite components if the real component is `+Infinity` and the imaginary component is finite and nonzero', function test( t ) {
	var v;

	v = cexpf( new Complex64( PINF, 1.0 ) );
	t.strictEqual( realf( v ), PINF, 'returns expected value' );
	t.strictEqual( imagf( v ), PINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+0.0` for both components if the real component is `-Infinity` and the imaginary component is `0.0`', function test( t ) {
	var v;

	v = cexpf( new Complex64( NINF, 0.0 ) );
	t.strictEqual( isPositiveZerof( realf( v ) ), true, 'returns expected value' );
	t.strictEqual( isPositiveZerof( imagf( v ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-Infinity` and `NaN` if the real component is `+Infinity` and the imaginary component is `-Infinity`', function test( t ) {
	var v;

	v = cexpf( new Complex64( PINF, NINF ) );
	t.strictEqual( realf( v ), NINF, 'returns expected value' );
	t.strictEqual( isnanf( imagf( v ) ), true, 'returns expected value' );
	t.end();
});
